// Build a minimal, valid CGIF configuration using a file path (avoids callback requirement)
// Enforce small dimensions to keep buffers < 2048 bytes total.
unsigned w = (unsigned)(*FUZZ_PARAM(unsigned int) % 32u) + 1u; // [1,32]
unsigned h = (unsigned)(*FUZZ_PARAM(unsigned int) % 32u) + 1u; // [1,32]
// Choose a global palette size as a power of two in [2,256]
unsigned pow2 = (unsigned)(*FUZZ_PARAM(unsigned int) % 8u) + 1u; // 1..8
unsigned numEntries = 1u << pow2; // 2..256
// Create a palette with numEntries entries (3 bytes per entry: RGB)
std::string palSeed = FUZZ_PARAM_STR();
std::vector<uint8_t> gpal; gpal.resize(numEntries * 3u);
for (size_t i = 0; i < gpal.size(); ++i) { gpal[i] = (uint8_t)palSeed[i % palSeed.size()]; }

CGIF_Config cfg; // user-managed, stack-lifetime is sufficient for cgif_newgif
cfg.pGlobalPalette = gpal.data();
cfg.numGlobalPaletteEntries = (uint16_t)numEntries;
cfg.width  = (uint16_t)w;
cfg.height = (uint16_t)h;
// Generate a valid output target: use a filename and keep callback NULL (mutually exclusive)
cfg.path    = FUZZ_PARAM_FILENAME();
cfg.pWriteFn = nullptr;
cfg.pContext = nullptr;
// Keep flags minimal/consistent to avoid conflicting modes
cfg.attrFlags = 0u; // no special attributes
cfg.genFlags  = 0u; // no special generation flags
// Loop count (0 often means infinite); choose small number
cfg.numLoops = (uint16_t)(*FUZZ_PARAM(unsigned int) % 5u);

// Create the GIF handle
CGIF* pGIF = cgif_newgif(&cfg);
if (!pGIF) { FUZZ_BAIL(); }

// Track essential attributes for downstream stubs
FUZZ_SET_ATTR_INT(pGIF, "width",  (int)w);
FUZZ_SET_ATTR_INT(pGIF, "height", (int)h);
FUZZ_SET_ATTR_INT(pGIF, "palette_entries", (int)numEntries);
FUZZ_SET_ATTR_INT(pGIF, "closed", 0);
// pGIF is returned as an output (persistent owned handle)

// Validate that the handle is open and we have required attributes
if (FUZZ_GET_ATTR_INT(pGIF, "closed")) { FUZZ_BAIL(); }
int w = FUZZ_GET_ATTR_INT(pGIF, "width");
int h = FUZZ_GET_ATTR_INT(pGIF, "height");
int palN = FUZZ_GET_ATTR_INT(pGIF, "palette_entries");
if (w <= 0 || h <= 0 || palN <= 0) { FUZZ_BAIL(); }

// Prepare indexed image data of size w*h with indices within [0, palN-1]
size_t numPx = (size_t)w * (size_t)h;
std::string seed = FUZZ_PARAM_STR();
std::vector<uint8_t> img; img.resize(numPx);
for (size_t i = 0; i < numPx; ++i) { img[i] = (uint8_t)(seed[i % seed.size()] % palN); }

// Build a frame config that uses the global color table only
CGIF_FrameConfig fcfg;
fcfg.pLocalPalette = nullptr;
fcfg.numLocalPaletteEntries = 0;
fcfg.pImageData = img.data();
fcfg.attrFlags = 0u; // no interlace, no transparency, etc.
fcfg.genFlags  = 0u; // no special generation flags
fcfg.delay = (uint16_t)(*FUZZ_PARAM(unsigned int) % 200u); // up to 2 seconds
fcfg.transIndex = 0; // ignored because no transparency flags

int rc = cgif_addframe(pGIF, &fcfg);
// Nonzero indicates an error path; we bail to avoid cascading misuse.
if (rc != 0) { FUZZ_BAIL(); }

// Return pGIF as output to keep it alive for further operations

// Ensure not already closed
if (FUZZ_GET_ATTR_INT(pGIF, "closed")) { FUZZ_BAIL(); }
int rc = cgif_close(pGIF);
// Mark as closed regardless of rc to prevent reuse; caller must not use after close
FUZZ_SET_ATTR_INT(pGIF, "closed", 1);
// Check return code semantics; nonzero indicates an error but is a valid outcome for fuzzing
// Do not return pGIF so the runtime drops ownership

// Minimal RGB GIF configuration using a file path target
unsigned w = (unsigned)(*FUZZ_PARAM(unsigned int) % 32u) + 1u;
unsigned h = (unsigned)(*FUZZ_PARAM(unsigned int) % 32u) + 1u;
CGIFrgb_Config cfg; // user-managed on stack
cfg.pWriteFn = nullptr;
cfg.pContext = nullptr;
cfg.path = FUZZ_PARAM_FILENAME();
cfg.attrFlags = 0u;
cfg.genFlags  = 0u;
cfg.numLoops = (uint16_t)(*FUZZ_PARAM(unsigned int) % 5u);
cfg.width  = (uint16_t)w;
cfg.height = (uint16_t)h;

CGIFrgb* pGIF_rgb = cgif_rgb_newgif(&cfg);
if (!pGIF_rgb) { FUZZ_BAIL(); }
// Track canvas and open-state for subsequent calls
FUZZ_SET_ATTR_INT(pGIF_rgb, "width",  (int)w);
FUZZ_SET_ATTR_INT(pGIF_rgb, "height", (int)h);
FUZZ_SET_ATTR_INT(pGIF_rgb, "closed", 0);
// Return the new handle

// Validate handle state and retrieve dimensions
if (FUZZ_GET_ATTR_INT(pGIF_rgb, "closed")) { FUZZ_BAIL(); }
int w = FUZZ_GET_ATTR_INT(pGIF_rgb, "width");
int h = FUZZ_GET_ATTR_INT(pGIF_rgb, "height");
if (w <= 0 || h <= 0) { FUZZ_BAIL(); }

// Select channel format and compute bytes per pixel
int useRGBA = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int bpp = useRGBA ? 4 : 3;
// Prepare raw pixel buffer of size w*h*bpp
size_t nbytes = (size_t)w * (size_t)h * (size_t)bpp;
std::string seed = FUZZ_PARAM_STR();
std::vector<uint8_t> pixels; pixels.resize(nbytes);
for (size_t i = 0; i < nbytes; ++i) { pixels[i] = (uint8_t)seed[i % seed.size()]; }

CGIFrgb_FrameConfig fcfg;
fcfg.pImageData = pixels.data();
fcfg.fmtChan = useRGBA ? CGIF_CHAN_FMT_RGBA : CGIF_CHAN_FMT_RGB;
fcfg.attrFlags = 0u; // keep attributes minimal to satisfy API
fcfg.genFlags  = 0u; // no special generation flags
fcfg.delay = (uint16_t)(*FUZZ_PARAM(unsigned int) % 200u);

cgif_result res = cgif_rgb_addframe(pGIF_rgb, &fcfg);
// Non-OK results are valid error paths; bail to isolate failing paths
if (res != CGIF_OK) { FUZZ_BAIL(); }

// Keep handle alive for more frames or close

// Ensure not already closed
if (FUZZ_GET_ATTR_INT(pGIF_rgb, "closed")) { FUZZ_BAIL(); }
cgif_result res = cgif_rgb_close(pGIF_rgb);
// Mark closed to prevent reuse regardless of result
FUZZ_SET_ATTR_INT(pGIF_rgb, "closed", 1);
// Do not return pGIF_rgb; runtime will drop it

