import random
from typing import List

def _pattern_solid(width: int, height: int, idx: int) -> bytes:
    return bytes([idx & 0xFF]) * (width * height)

def _pattern_checker(width: int, height: int, palN: int) -> bytes:
    data = bytearray(width * height)
    for y in range(height):
        for x in range(width):
            data[y*width + x] = ((x // 4) ^ (y // 4)) % palN
    return bytes(data)

def _pattern_grad_x(width: int, height: int, palN: int) -> bytes:
    data = bytearray(width * height)
    for y in range(height):
        for x in range(width):
            data[y*width + x] = (x * palN) // max(1, width)
    return bytes(data)

def _pattern_grad_y(width: int, height: int, palN: int) -> bytes:
    data = bytearray(width * height)
    for y in range(height):
        val = (y * palN) // max(1, height)
        row_start = y*width
        data[row_start:row_start+width] = bytes([val]) * width
    return bytes(data)

def _pattern_stripes(width: int, height: int, palN: int, vertical: bool) -> bytes:
    data = bytearray(width * height)
    for y in range(height):
        for x in range(width):
            band = (x // 8) if vertical else (y // 8)
            data[y*width + x] = band % palN
    return bytes(data)

def _pattern_bulls_eye(width: int, height: int, palN: int) -> bytes:
    cx = (width - 1) / 2.0
    cy = (height - 1) / 2.0
    data = bytearray(width * height)
    for y in range(height):
        for x in range(width):
            r = int(((x - cx)**2 + (y - cy)**2) ** 0.5)
            data[y*width + x] = (r // 3) % palN
    return bytes(data)

def _pattern_from_seed_string(width: int, height: int, palN: int, s: bytes) -> bytes:
    # Map each pixel deterministically from seed bytes into palette range
    if not s:
        s = b"0"
    data = bytearray(width * height)
    L = len(s)
    for i in range(width * height):
        b = s[i % L]
        data[i] = b % palN
    return bytes(data)

def _choose_dimensions(rng: random.Random) -> (int, int):
    # Favor common small sizes, but include some larger within limit (<=4096 bytes total not required by stub, but we keep modest)
    presets = [(1,1), (2,2), (4,4), (8,8), (16,16), (32,32), (40,30), (64,32), (32,64)]
    if rng.random() < 0.6:
        return rng.choice(presets)
    # Random within reasonable bounds; keep product <= 4096 to be small
    max_px = 4096
    w = rng.randint(1, 128)
    h = max(1, min(128, max_px // w))
    h = rng.randint(1, h)
    return w, h

def _choose_palette_size(rng: random.Random) -> int:
    # Valid GIF palette sizes are powers of two up to 256, but the stub only requires palN > 0.
    # To remain valid for real encoder paths, prefer 2..256.
    choices = [2, 4, 8, 16, 32, 64, 128, 256]
    if rng.random() < 0.85:
        return rng.choice(choices)
    # Occasionally pick a non-power-of-two but <=256 to exercise index handling within stub
    return rng.randint(1, 256)

def _build_seed_string(rng: random.Random, palN: int, target_len: int) -> bytes:
    # Create a seed that the stub will use to fill pixels modulo palN.
    modes = [
        "bytes_range", "repeating_indices", "ascii_text", "structured_blocks",
        "single_value", "ascending", "descending"
    ]
    mode = rng.choice(modes)
    length = rng.randint(1, max(1, min(256, target_len)))

    if mode == "bytes_range":
        return bytes((i % 256 for i in range(length)))
    if mode == "repeating_indices":
        period = rng.choice([1, 2, 3, 4, 5, 7, 8, 16])
        return bytes(((i % period) % palN for i in range(length)))
    if mode == "ascii_text":
        corpus = [
            b"GIF89a", b"palettes", b"indices", b"frame", b"animate", b"cgif",
            b"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
        ]
        s = bytearray()
        while len(s) < length:
            s += rng.choice(corpus)
        return bytes(s[:length])
    if mode == "structured_blocks":
        block = bytes([rng.randrange(0, palN) for _ in range(rng.randint(2, 16))])
        reps = max(1, length // max(1, len(block)))
        return (block * reps)[:length] or block
    if mode == "single_value":
        return bytes([rng.randrange(0, palN)]) * length
    if mode == "ascending":
        return bytes(((i % 256) for i in range(length)))
    if mode == "descending":
        return bytes(((255 - (i % 256)) for i in range(length)))
    return bytes([0]) * length

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose canvas and palette consistent with the stub's expectations
    w, h = _choose_dimensions(rng)
    palN = _choose_palette_size(rng)

    # Build a seed string that the stub's FUZZ_PARAM_STR will use
    # We try to make its modulo mapping produce diverse indices.
    seed_bytes = _build_seed_string(rng, palN, w * h)

    # Additionally, build an alternate valid image following common patterns.
    patterns = [
        lambda: _pattern_from_seed_string(w, h, palN, seed_bytes),
        lambda: _pattern_solid(w, h, rng.randrange(0, palN)),
        lambda: _pattern_checker(w, h, palN),
        lambda: _pattern_grad_x(w, h, palN),
        lambda: _pattern_grad_y(w, h, palN),
        lambda: _pattern_stripes(w, h, palN, True),
        lambda: _pattern_stripes(w, h, palN, False),
        lambda: _pattern_bulls_eye(w, h, palN),
    ]
    img = rng.choice(patterns)()

    # Construct a small header so a driver could optionally parse dimensions/palette size.
    # Layout: 2 bytes width (LE), 2 bytes height (LE), 2 bytes palN (LE), 1 byte mode tag, then seed_bytes, then img.
    # This remains opaque to the stub but provides structured data to any harness that maps FUZZ_PARAM_STR from this buffer.
    mode_tag = rng.randrange(0, 256)
    header = (
        w.to_bytes(2, 'little') +
        h.to_bytes(2, 'little') +
        palN.to_bytes(2, 'little') +
        bytes([mode_tag])
    )

    out = header + seed_bytes + img
    # Ensure size limit
    return out[:4096]
